-- =============================================================================
-- Baza vežbi za NOVU instalaciju (uvesti posle shema.sql i, po želji, podaci-primer.sql).
-- =============================================================================
-- 109 najčešćih vežbi u teretani: težina izvođenja, oprema, glavni i pomoćni mišići, kratka tehnika (sr/en).
-- Ključevi opreme i mišića: app/vezbe.php. Spisak: dev/vezbe/lista.py, SQL: dev/vezbe/napravi-sql.py.
-- YouTube linkove upisuje trener (Baza vežbi). Sve vežbe može da menja ili sakrije.

SET NAMES utf8mb4;

-- Vežba koja već postoji (isti naziv) zadržava sve što je trener upisao; popunjava se samo ono što je prazno
ON DUPLICATE KEY UPDATE naziv_en = IF(naziv_en = '', VALUES(naziv_en), naziv_en), tezina = IF(tezina = '', VALUES(tezina), tezina),
  oprema = IF(oprema = '', VALUES(oprema), oprema), misici = IF(misici = '', VALUES(misici), misici),
  misici_pomocni = IF(misici_pomocni = '', VALUES(misici_pomocni), misici_pomocni),
  tehnika = IF(tehnika IS NULL OR tehnika = '', VALUES(tehnika), tehnika), tehnika_en = IF(tehnika_en IS NULL OR tehnika_en = '', VALUES(tehnika_en), tehnika_en);
